  let c01 = textureLoad(t_bind11, vec2<i32>(x0, y1), 0);
  let c11 = textureLoad(t_bind11, vec2<i32>(x1, y1), 0);
  let top = mix(c00, c10, frac.x);
  let bot = mix(c01, c11, frac.x);
